    [Inject] IMessageService MessageService { get; set; } = null!;

    ArchiveModel newArchiveModel = new();
    bool isProcessing;
    string keywordsString = string.Empty;

    protected override void OnInitialized()
    {
        base.OnInitialized();
        if (Configuration?.RecallHintKeywords != null)
        {
            keywordsString = string.Join(",", Configuration.RecallHintKeywords);
        }
    }

    protected override void OnParametersSet()
    {
        base.OnParametersSet();
        if (Configuration?.RecallHintKeywords != null)
        {
            keywordsString = string.Join(",", Configuration.RecallHintKeywords);
        }
    }

    private Task UpdateKeywords()
    {
        if (Configuration != null)
        {
            Configuration.RecallHintKeywords = keywordsString
                .Split(',', StringSplitOptions.RemoveEmptyEntries)
                .Select(k => k.Trim())
                .Where(k => !string.IsNullOrEmpty(k))
                .ToList();
        }
        return Task.CompletedTask;
    }

    class ArchiveModel
    {
        public string Summary { get; set; } = "";
        public string Content { get; set; } = "";
    }

    async Task HandleAddArchive()
    {
        if (Module == null) return;
        if (string.IsNullOrWhiteSpace(newArchiveModel.Summary) || string.IsNullOrWhiteSpace(newArchiveModel.Content))
        {
            MessageService.Warning("概述和内容都不能为空喵！");
            return;
        }

        isProcessing = true;
        try
        {
            int maxLevel = Configuration.MaxCompressionLevel;
            await Module.InsertMemory(maxLevel, newArchiveModel.Summary, newArchiveModel.Content, DateTime.Now, DateTime.Now);
            MessageService.Success("核心记忆已成功存入喵！");
            newArchiveModel = new ArchiveModel();
        }
        catch (Exception ex)
        {
            MessageService.Error($"存入失败: {ex.Message}");
        }
        finally
        {
            isProcessing = false;
        }
    }

